export type CompanionState = "idle" | "listening" | "thinking" | "searching" | "learning" | "building" | "awaiting_approval" | "success" | "failed" | "offline";

export const statePriority: Record<CompanionState, number> = {
  offline: 0,
  idle: 1,
  listening: 2,
  success: 3,
  thinking: 4,
  searching: 4,
  learning: 4,
  building: 4,
  awaiting_approval: 5,
  failed: 6
};

export const safeLabels = new Set([
  "Ready", "Listening", "Thinking", "Searching", "Learning", "Building",
  "Approval needed", "Complete", "Something needs attention", "Offline",
  "Feed refreshed", "Saved", "Ignored", "Review recorded", "Lesson complete",
  "Artifact created", "Theme updated", "Domain created", "Analysis lens updated"
]);

export function sanitizeLabel(label: unknown, state: CompanionState): string {
  if (typeof label === "string" && safeLabels.has(label)) return label;
  return ({
    idle: "Ready", listening: "Listening", thinking: "Thinking", searching: "Searching",
    learning: "Learning", building: "Building", awaiting_approval: "Approval needed",
    success: "Complete", failed: "Something needs attention", offline: "Offline"
  })[state];
}

export function shouldApply(current: CompanionState, incoming: CompanionState): boolean {
  return statePriority[incoming] >= statePriority[current] || incoming === "idle";
}
