import { sanitizeLabel, shouldApply, type CompanionState } from "./state";
import { APP_SURFACE, parseHeronContext, persistHeronContext, restoreHeronContext } from "./context.mjs";

const bundleScript = document.currentScript as HTMLScriptElement | null;
declare const __HERON_COMPANION_VERSION__: string;
const companionRelease = __HERON_COMPANION_VERSION__;

function releaseAssetUrl(fileName: string): string {
  const asset = bundleScript?.src ? new URL(`./${fileName}`, bundleScript.src) : new URL(`/vendor/heron-companion/${fileName}`, window.location.href);
  asset.searchParams.set("v", companionRelease);
  return asset.href;
}

const stylesheetUrl = releaseAssetUrl("heron-companion.css");
const atlasUrl = releaseAssetUrl("heron-companion-v3.webp");
const atlasFallbackUrl = releaseAssetUrl("heron-companion-v3.png");

export type HeronApp = "quantum" | "feed" | "learn" | "watch" | "graph" | "heronclient";
export type LocalCompanionEvent = { type: "navigation" | "refresh" | "save" | "ignore" | "review" | "lesson_complete" | "artifact_created" | "knowledge_object_updated" | "receipt_opened" | "domain_created" | "archetypal_mode_changed" | "error" | "theme_changed"; label?: string; domain?: string };
type SafeZone = "top-left" | "top-right" | "bottom-left" | "bottom-right";
type CompanionPosition = { x: number; y: number };
type HeronContext = { version: number; sourceSurface: string; targetSurface: string; traceId?: string; capsuleId?: string; semanticObjectId?: string; projectionId?: string; learningUnitId?: string; learningDomainId?: string; archetypalModes?: string[]; actionIntentId?: string; sourceUrl?: string; sourceTitle?: string; issuedAt?: string };
type SurfaceContext = { title?: string; url?: string; summary?: string; objectId?: string };
type Activity = { id: string; kind: "needs_input" | "blocked" | "ready" | "running" | "insight"; priority: number; surface: string; title: string; summary: string; href: string; unread: boolean; occurredAt: string; refs: Array<{ kind: string; id: string }> };
type Message = { id?: string; role: string; content: string; created_at?: string; pending?: boolean };
type Bootstrap = { version?: number; enabled?: boolean; state?: CompanionState; label?: string; activities?: Activity[]; websocketToken?: string; websocketUrl?: string; capabilities?: string[]; preferences?: { minimized?: boolean; hidden?: boolean; reduced_motion?: boolean; zone?: SafeZone } };

const localState: Record<LocalCompanionEvent["type"], CompanionState> = { navigation: "searching", refresh: "searching", save: "success", ignore: "idle", review: "learning", lesson_complete: "success", artifact_created: "success", knowledge_object_updated: "success", receipt_opened: "idle", domain_created: "success", archetypal_mode_changed: "learning", error: "failed", theme_changed: "idle" };
const localLabel: Record<LocalCompanionEvent["type"], string> = { navigation: "Searching", refresh: "Feed refreshed", save: "Saved", ignore: "Ignored", review: "Review recorded", lesson_complete: "Lesson complete", artifact_created: "Artifact created", knowledge_object_updated: "Knowledge object updated", receipt_opened: "Receipt opened", domain_created: "Domain created", archetypal_mode_changed: "Analysis lens updated", error: "Something needs attention", theme_changed: "Theme updated" };
const spriteRows: Record<CompanionState, number> = { idle: 0, listening: 1, thinking: 2, searching: 2, learning: 3, building: 4, awaiting_approval: 5, success: 6, failed: 7, offline: 8 };
const activityRank = { needs_input: 5, blocked: 4, ready: 3, insight: 2, running: 1 };

function escape(value: unknown): string { return String(value || "").replace(/[&<>"']/g, char => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "\"": "&quot;", "'": "&#39;" })[char]!); }
function sameOriginUrl(url: string): boolean { try { return new URL(url, window.location.href).origin === window.location.origin; } catch { return false; } }

class CompanionController {
  private host?: HTMLElement; private root?: ShadowRoot; private appId: HeronApp = "quantum";
  private state: CompanionState = "idle"; private label = "Ready"; private zone: SafeZone = "bottom-right";
  private minimized = false; private open = false; private activeTab: "activity" | "chat" = "activity";
  private socket?: WebSocket; private reconnectTimer?: number; private reconnectAttempt = 0; private transientTimer?: number;
  private lastSequence = 0;
  private theme: Record<string, string> = {}; private destroyed = false; private anonymous = false;
  private bootstrapUrl = "/api/v2/companion/bootstrap"; private lastTransition = { signature: "", at: 0 };
  private themeSheet?: CSSStyleSheet; private context?: HeronContext; private contextDismissed = false;
  private surfaceContext?: SurfaceContext; private activities: Activity[] = []; private capabilities = new Set<string>();
  private messages: Message[] = []; private conversationId?: string; private activeRunId?: string; private draft = "";
  private loading = false; private error = ""; private reducedMotion = false; private v3Enabled = false; private privateConnected = false;
  private position?: CompanionPosition; private suppressMascotClick = false;
  private onKeyDown = (event: KeyboardEvent): void => { if (event.key === "Escape" && this.open) { event.preventDefault(); this.open = false; this.render(); this.root?.querySelector<HTMLButtonElement>(".mascot")?.focus(); } };

  async init(options: { appId: HeronApp; bootstrapUrl?: string; anonymous?: boolean }): Promise<void> {
    if (document.querySelector("heron-companion[data-mounted='true']")) return;
    this.appId = options.appId; this.anonymous = Boolean(options.anonymous); this.bootstrapUrl = options.bootstrapUrl || this.bootstrapUrl;
    this.captureContext(); this.zone = (localStorage.getItem(`heron-companion-zone:${this.appId}`) as SafeZone) || "bottom-right"; this.position = this.restorePosition();
    this.minimized = localStorage.getItem("heron-companion-minimized") === "true"; this.mount(); this.render();
    await this.bootstrap();
    document.addEventListener("visibilitychange", this.onVisibilityChange);
    window.addEventListener("resize", this.onResize, { passive: true });
  }

  emitLocal(event: LocalCompanionEvent): void { if (event.type in localState) this.setState(localState[event.type], localLabel[event.type], true); }
  getContext(): HeronContext | undefined { return this.context ? { ...this.context } : undefined; }
  setSurfaceContext(context?: SurfaceContext): void { this.surfaceContext = context ? { title: String(context.title || "").slice(0, 300), url: String(context.url || "").slice(0, 2048), summary: String(context.summary || "").slice(0, 4000), objectId: String(context.objectId || "").slice(0, 80) } : undefined; }
  setTheme(theme: Record<string, string>): void { const allowed = ["accent", "accent2", "ink", "surface"]; this.theme = Object.fromEntries(Object.entries(theme).filter(([key, value]) => allowed.includes(key) && /^#[0-9a-f]{3,8}$/i.test(value))); this.render(); }
  minimize(): void { this.minimized = true; this.open = false; localStorage.setItem("heron-companion-minimized", "true"); this.render(); }
  expand(): void { this.minimized = false; localStorage.setItem("heron-companion-minimized", "false"); this.render(); }
  destroy(): void { this.destroyed = true; this.socket?.close(); if (this.reconnectTimer) clearTimeout(this.reconnectTimer); document.removeEventListener("visibilitychange", this.onVisibilityChange); window.removeEventListener("resize", this.onResize); this.host?.remove(); }

  private onVisibilityChange = (): void => { this.host?.toggleAttribute("data-paused", document.hidden); };
  private onResize = (): void => { this.applyPosition(); };
  private apiPath(suffix: string): string { const base = new URL(this.bootstrapUrl, window.location.href); base.pathname = base.pathname.replace(/\/bootstrap$/, suffix); base.search = ""; return base.toString(); }
  private async request<T>(suffix: string, init?: RequestInit): Promise<T> { const response = await fetch(this.apiPath(suffix), { credentials: "include", ...init, headers: { "content-type": "application/json", ...(init?.headers || {}) } }); const value = await response.json().catch(() => ({})); if (!response.ok) throw new Error((value as any).error || "Heron is unavailable"); return value as T; }

  private async bootstrap(): Promise<void> {
    try {
      const response = await fetch(this.bootstrapUrl, { method: "POST", credentials: "include", headers: { "content-type": "application/json", "x-heron-app": this.appId }, body: JSON.stringify({ appId: this.appId, anonymous: this.anonymous }) });
      if (!response.ok) throw new Error("bootstrap unavailable"); const value = await response.json() as Bootstrap;
      if (value.preferences?.hidden) return this.destroy();
      this.v3Enabled = value.version === 3 && value.enabled !== false; this.zone = value.preferences?.zone || this.zone;
      this.minimized = value.preferences?.minimized ?? this.minimized; this.reducedMotion = Boolean(value.preferences?.reduced_motion) || matchMedia("(prefers-reduced-motion: reduce)").matches || Boolean((navigator as any).connection?.saveData);
      this.activities = this.rankActivities(value.activities || []); this.capabilities = new Set(value.capabilities || []); this.privateConnected = this.capabilities.has("activity") || this.capabilities.has("compact_chat"); this.setState(value.state || "idle", value.label, false);
      if (value.websocketToken && value.websocketUrl) this.connect(value.websocketUrl, value.websocketToken);
    } catch { this.setState(this.privateConnected ? "offline" : "idle", this.privateConnected ? "Offline" : "Ready", false); }
  }

  private async refreshSnapshot(): Promise<void> {
    if (!this.capabilities.has("activity")) return;
    try { const value = await this.request<{ state: CompanionState; label: string; activities: Activity[] }>("/snapshot"); this.activities = this.rankActivities(value.activities || []); this.setState(value.state || "idle", value.label, false); this.render(); } catch { /* Socket retries own connectivity state. */ }
  }

  private rankActivities(values: Activity[]): Activity[] { return [...values].filter(value => value?.id && value?.kind in activityRank).sort((a, b) => (activityRank[b.kind] - activityRank[a.kind]) || b.priority - a.priority || Date.parse(b.occurredAt) - Date.parse(a.occurredAt)).slice(0, 50); }
  private mount(): void { this.host = document.createElement("heron-companion"); this.host.dataset.mounted = "true"; this.host.dataset.app = this.appId; this.root = this.host.attachShadow({ mode: "open" }); this.root.addEventListener("keydown", this.onKeyDown); document.body.append(this.host); }
  private captureContext(): void { const expectedTarget = APP_SURFACE[this.appId as keyof typeof APP_SURFACE]; if (!expectedTarget) return; try { const fromUrl = parseHeronContext(window.location.href, expectedTarget) as HeronContext | null; this.context = fromUrl || restoreHeronContext(expectedTarget, window.sessionStorage) as HeronContext | null || undefined; if (!this.context) return; persistHeronContext(this.context, window.sessionStorage); this.surfaceContext = { title: this.context.sourceTitle, url: this.context.sourceUrl, objectId: this.context.semanticObjectId }; queueMicrotask(() => window.dispatchEvent(new CustomEvent("heron:context-received", { detail: { ...this.context } }))); } catch (error) { queueMicrotask(() => window.dispatchEvent(new CustomEvent("heron:context-rejected", { detail: { reason: error instanceof Error ? error.message : "Invalid Heron context" } }))); } }
  private setState(state: CompanionState, label?: string, transient = false): void { if (!shouldApply(this.state, state) && transient) return; const nextLabel = sanitizeLabel(label, state); const signature = `${state}:${nextLabel}`; if (this.lastTransition.signature === signature && Date.now() - this.lastTransition.at < 500) return; this.lastTransition = { signature, at: Date.now() }; this.state = state; this.label = nextLabel; this.render(); window.dispatchEvent(new CustomEvent("heron:companion-state", { detail: { appId: this.appId, state } })); if (this.transientTimer) clearTimeout(this.transientTimer); if (transient && !["failed", "awaiting_approval"].includes(state)) this.transientTimer = window.setTimeout(() => this.setState(this.socket?.readyState === WebSocket.OPEN || !this.privateConnected ? "idle" : "offline", undefined, false), 2200); }

  private connect(url: string, token: string): void {
    if (this.destroyed) return; this.socket?.close(); this.socket = new WebSocket(url, `heron-companion.${token}`);
    this.socket.onopen = () => { this.reconnectAttempt = 0; void this.refreshSnapshot(); };
    this.socket.onmessage = message => { try { const event = JSON.parse(String(message.data)); if (event.version !== 1 || !Number.isSafeInteger(event.sequence) || event.sequence < 0) return; if (event.type === "connection.ready") { this.lastSequence = 0; return; } if (event.sequence <= this.lastSequence) return; if (event.sequence > this.lastSequence + 1) void this.refreshSnapshot(); this.lastSequence = event.sequence; if (event.type === "message.delta" && event.conversationId) this.applyDelta(event); else { const states: CompanionState[] = ["idle","listening","thinking","searching","learning","building","awaiting_approval","success","failed","offline"]; if (states.includes(event.state)) this.setState(event.state, event.label, false); if (["message.completed","approval.requested","insight.created","artifact.created"].includes(event.type)) { if (event.conversationId && event.type === "message.completed") void this.loadConversation(event.conversationId); void this.refreshSnapshot(); } } } catch { /* Ignore malformed or non-public events. */ } };
    this.socket.onclose = () => { if (this.destroyed) return; this.setState(this.privateConnected ? "offline" : "idle", this.privateConnected ? "Offline" : "Ready", false); const delay = Math.min(30000, 750 * 2 ** this.reconnectAttempt++) + Math.random() * 300; this.reconnectTimer = window.setTimeout(() => void this.rebootstrap(), delay); };
  }
  private async rebootstrap(): Promise<void> { if (this.destroyed) return; await this.bootstrap(); if (this.socket?.readyState !== WebSocket.OPEN) { const delay = Math.min(30000, 750 * 2 ** this.reconnectAttempt++); this.reconnectTimer = window.setTimeout(() => void this.rebootstrap(), delay); } }
  private applyDelta(event: any): void { this.conversationId = event.conversationId; this.activeRunId = event.runId; let pending = this.messages.find(message => message.pending); if (!pending) { pending = { role: "assistant", content: "", pending: true }; this.messages.push(pending); } pending.content += String(event.delta || ""); this.render(); this.scrollMessages(); }
  private async loadConversation(id: string): Promise<void> { try { const value = await this.request<{ messages: Message[] }>(`/conversations/${encodeURIComponent(id)}`); this.conversationId = id; this.activeRunId = undefined; this.messages = value.messages || []; this.render(); this.scrollMessages(); } catch { /* Snapshot remains usable if history is unavailable. */ } }
  private async sendMessage(): Promise<void> { const message = this.draft.trim(); if (!message || this.loading) return; this.loading = true; this.error = ""; this.messages.push({ role: "user", content: message }); this.messages.push({ role: "assistant", content: "", pending: true }); this.draft = ""; this.render(); try { const value = await this.request<{ runId: string; conversationId: string }>("/runs", { method: "POST", body: JSON.stringify({ message, conversationId: this.conversationId, appId: this.appId, context: this.surfaceContext }) }); this.activeRunId = value.runId; this.conversationId = value.conversationId; this.setState("thinking", "Thinking", false); } catch (error) { this.messages = this.messages.filter(item => !item.pending); this.error = error instanceof Error ? error.message : "Message could not be sent"; } finally { this.loading = false; this.render(); this.scrollMessages(); } }
  private async markActivity(activity: Activity, action: "read" | "dismiss"): Promise<void> { try { await this.request(`/activities/${encodeURIComponent(activity.id)}`, { method: "POST", body: JSON.stringify({ action }) }); if (action === "dismiss") this.activities = this.activities.filter(item => item.id !== activity.id); else activity.unread = false; this.render(); if (action === "read" && activity.href) { if (sameOriginUrl(activity.href)) window.location.assign(activity.href); else window.open(activity.href, "_blank", "noopener,noreferrer"); } } catch (error) { this.error = error instanceof Error ? error.message : "Activity could not be updated"; this.render(); } }
  private positionKey(): string { return `heron-companion-position:${this.appId}`; }
  private restorePosition(): CompanionPosition | undefined { try { const value = JSON.parse(localStorage.getItem(this.positionKey()) || "null"); if (Number.isFinite(value?.x) && Number.isFinite(value?.y) && value.x >= 0 && value.x <= 1 && value.y >= 0 && value.y <= 1) return value; } catch { localStorage.removeItem(this.positionKey()); } return undefined; }
  private resetPosition(): void { this.position = undefined; this.zone = "bottom-right"; localStorage.removeItem(this.positionKey()); localStorage.setItem(`heron-companion-zone:${this.appId}`, this.zone); this.render(); }
  private placement(element: HTMLElement): { left: number; top: number; width: number; height: number; maxLeft: number; maxTop: number } { const rect = element.getBoundingClientRect(); const width = rect.width || 124; const height = rect.height || 134; const edge = 8; const bottomEdge = matchMedia("(max-width: 640px)").matches ? 68 : edge; return { left: rect.left, top: rect.top, width, height, maxLeft: Math.max(edge, window.innerWidth - width - edge), maxTop: Math.max(edge, window.innerHeight - height - bottomEdge) }; }
  private setFreePosition(element: HTMLElement, left: number, top: number): void { const metrics = this.placement(element); const clampedLeft = Math.min(metrics.maxLeft, Math.max(8, left)); const clampedTop = Math.min(metrics.maxTop, Math.max(8, top)); element.classList.add("free-position"); element.style.setProperty("--heron-x", `${clampedLeft}px`); element.style.setProperty("--heron-y", `${clampedTop}px`); this.zone = `${clampedTop + metrics.height / 2 < window.innerHeight / 2 ? "top" : "bottom"}-${clampedLeft + metrics.width / 2 < window.innerWidth / 2 ? "left" : "right"}` as SafeZone; element.classList.remove("top-left", "top-right", "bottom-left", "bottom-right"); element.classList.add(this.zone); const trayWidth = Math.min(390, window.innerWidth - 32); const trayHeight = Math.min(610, window.innerHeight - 32); const trayLeft = this.zone.endsWith("left") ? clampedLeft + 100 : clampedLeft + 24 - trayWidth; const trayTop = this.zone.startsWith("top") ? clampedTop + 12 : clampedTop + metrics.height - 12 - trayHeight; element.style.setProperty("--heron-tray-x", `${Math.max(16, Math.min(window.innerWidth - trayWidth - 16, trayLeft))}px`); element.style.setProperty("--heron-tray-y", `${Math.max(16, Math.min(window.innerHeight - trayHeight - 16, trayTop))}px`); }
  private applyPosition(): void { const element = this.root?.querySelector<HTMLElement>(".companion"); if (!element || !this.position) return; const metrics = this.placement(element); this.setFreePosition(element, 8 + this.position.x * (metrics.maxLeft - 8), 8 + this.position.y * (metrics.maxTop - 8)); }
  private persistPosition(element: HTMLElement): void { const metrics = this.placement(element); this.position = { x: metrics.maxLeft === 8 ? 0 : Math.min(1, Math.max(0, (metrics.left - 8) / (metrics.maxLeft - 8))), y: metrics.maxTop === 8 ? 0 : Math.min(1, Math.max(0, (metrics.top - 8) / (metrics.maxTop - 8))) }; localStorage.setItem(this.positionKey(), JSON.stringify(this.position)); localStorage.setItem(`heron-companion-zone:${this.appId}`, this.zone); }
  private bindMascot(mascot: HTMLButtonElement, companion: HTMLElement): void {
    let pointerId = -1; let startX = 0; let startY = 0; let startLeft = 0; let startTop = 0; let lastDx = 0; let lastDy = 0; let dragging = false;
    const move = (event: PointerEvent): void => { if (event.pointerId !== pointerId) return; lastDx = event.clientX - startX; lastDy = event.clientY - startY; if (!dragging && Math.hypot(lastDx, lastDy) < 5) return; dragging = true; companion.classList.add("dragging"); companion.style.setProperty("--heron-drag-x", `${lastDx}px`); companion.style.setProperty("--heron-drag-y", `${lastDy}px`); };
    const finish = (event: PointerEvent): void => { if (event.pointerId !== pointerId) return; if (mascot.hasPointerCapture(pointerId)) mascot.releasePointerCapture(pointerId); pointerId = -1; companion.classList.remove("dragging"); companion.style.removeProperty("--heron-drag-x"); companion.style.removeProperty("--heron-drag-y"); window.removeEventListener("pointermove", move); window.removeEventListener("pointerup", finish); window.removeEventListener("pointercancel", finish); if (dragging) { this.setFreePosition(companion, startLeft + lastDx, startTop + lastDy); this.persistPosition(companion); this.suppressMascotClick = event.type === "pointerup"; } };
    mascot.addEventListener("pointerdown", event => { if (event.button !== 0) return; event.preventDefault(); const rect = companion.getBoundingClientRect(); pointerId = event.pointerId; startX = event.clientX; startY = event.clientY; startLeft = rect.left; startTop = rect.top; lastDx = 0; lastDy = 0; dragging = false; mascot.setPointerCapture(pointerId); window.addEventListener("pointermove", move); window.addEventListener("pointerup", finish); window.addEventListener("pointercancel", finish); });
    mascot.addEventListener("click", () => { if (this.suppressMascotClick) { this.suppressMascotClick = false; return; } if (this.minimized) this.expand(); else { this.open = !this.open; this.render(); this.root?.querySelector<HTMLButtonElement>(this.open ? "[data-action='close']" : ".mascot")?.focus(); } });
  }
  private scrollMessages(): void { requestAnimationFrame(() => { const element = this.root?.querySelector<HTMLElement>(".messages"); if (element) element.scrollTop = element.scrollHeight; }); }

  private activityHtml(): string { if (!this.activities.length) return `<div class="empty"><strong>All clear</strong><span>Heron will collect work that needs attention here.</span></div>`; return `<div class="activity-list">${this.activities.map(activity => `<article class="activity ${activity.unread ? "unread" : ""}" data-kind="${activity.kind}"><button class="activity-open" data-activity-open="${escape(activity.id)}" type="button"><i aria-hidden="true"></i><span><small>${escape(activity.surface.replace("heronclient", "client"))}</small><strong>${escape(activity.title)}</strong><b>${escape(activity.summary)}</b></span><time>${escape(new Date(activity.occurredAt).toLocaleDateString(undefined, { month: "short", day: "numeric" }))}</time></button><button class="dismiss" data-activity-dismiss="${escape(activity.id)}" type="button" aria-label="Dismiss ${escape(activity.title)}" title="Dismiss">×</button></article>`).join("")}</div>`; }
  private chatHtml(): string { const messages = this.messages.length ? this.messages.map(message => `<article class="message ${message.role} ${message.pending ? "pending" : ""}"><small>${escape(message.role === "assistant" ? "Heron" : "You")}</small><p>${escape(message.content || (message.pending ? "Working…" : ""))}</p></article>`).join("") : `<div class="empty"><strong>Ask Heron</strong><span>${escape(this.surfaceContext?.title ? `Current context: ${this.surfaceContext.title}` : "Start a private system conversation.")}</span></div>`; return `<div class="messages">${messages}</div><form class="composer"><textarea rows="2" maxlength="100000" placeholder="Message Heron" aria-label="Message Heron">${escape(this.draft)}</textarea><button type="submit" aria-label="Send message" title="Send" ${this.loading ? "disabled" : ""}>↑</button></form>`; }

  private render(): void {
    if (!this.root) return; const accent = this.theme.accent || ({ quantum: "#b7f34a", feed: "#52d4ff", learn: "#bd8cff", watch: "#ffcf5a", graph: "#75f0b0", heronclient: "#ff9f43" })[this.appId];
    if ("adoptedStyleSheets" in this.root && "replaceSync" in CSSStyleSheet.prototype) { this.themeSheet ||= new CSSStyleSheet(); this.themeSheet.replaceSync(`:host{--heron-accent:${accent};--heron-accent-2:${this.theme.accent2 || "#58d7ff"};--heron-ink:${this.theme.ink || "#10151b"};--heron-surface:${this.theme.surface || "#f6f7ed"};--heron-atlas:image-set(url("${atlasUrl}") type("image/webp"),url("${atlasFallbackUrl}") type("image/png"));--sprite-row:${spriteRows[this.state] * 12.5}%}`); this.root.adoptedStyleSheets = [this.themeSheet]; }
    const contextHtml = this.context && !this.contextDismissed ? `<aside class="context-receipt" role="status"><div><small>CONTEXT · ${escape(this.context.sourceSurface)} → ${escape(this.context.targetSurface)}</small><strong>${escape(this.context.sourceTitle || this.context.learningDomainId || "Carried source context")}</strong></div><button data-action="dismiss-context" type="button" aria-label="Dismiss context">×</button></aside>` : "";
    this.root.innerHTML = `<link rel="stylesheet" href="${stylesheetUrl}">${contextHtml}<section class="companion ${this.zone} ${this.position ? "free-position" : ""} ${this.minimized ? "minimized" : ""} ${this.open ? "open" : ""} ${this.reducedMotion ? "reduced-motion" : ""}" data-state="${this.state}" aria-label="Heron: ${escape(this.label)}"><button class="mascot" type="button" aria-label="${this.open ? "Close" : "Open"} Heron"><span class="sprite" aria-hidden="true"></span><span class="status-dot" aria-hidden="true"></span></button><div class="status-bubble" role="status" aria-live="polite"><strong>Heron</strong><span>${escape(this.label)}</span></div>${this.v3Enabled && this.open ? `<section class="tray" aria-label="Heron companion"><header><div><strong>Heron</strong><span>${escape(this.label)}</span></div><div><button data-action="reset-position" type="button" aria-label="Reset Heron position" title="Reset position">⌖</button><button data-action="minimize" type="button" aria-label="Minimize Heron" title="Minimize">−</button><button data-action="close" type="button" aria-label="Close Heron" title="Close">×</button></div></header><nav aria-label="Companion view"><button class="${this.activeTab === "activity" ? "active" : ""}" data-tab="activity" type="button">Activity${this.activities.filter(item => item.unread).length ? `<b>${this.activities.filter(item => item.unread).length}</b>` : ""}</button><button class="${this.activeTab === "chat" ? "active" : ""}" data-tab="chat" type="button" ${this.capabilities.has("compact_chat") ? "" : "disabled"}>Chat</button></nav><div class="tray-body">${this.error ? `<p class="error" role="alert">${escape(this.error)}</p>` : ""}${this.activeTab === "activity" ? this.activityHtml() : this.chatHtml()}</div></section>` : ""}</section>`;
    const companion = this.root.querySelector<HTMLElement>(".companion"); const mascot = this.root.querySelector<HTMLButtonElement>(".mascot"); if (companion && mascot) this.bindMascot(mascot, companion); this.applyPosition();
    this.root.querySelector("[data-action='close']")?.addEventListener("click", () => { this.open = false; this.render(); this.root?.querySelector<HTMLButtonElement>(".mascot")?.focus(); }); this.root.querySelector("[data-action='reset-position']")?.addEventListener("click", () => this.resetPosition()); this.root.querySelector("[data-action='minimize']")?.addEventListener("click", () => this.minimize()); this.root.querySelector("[data-action='dismiss-context']")?.addEventListener("click", () => { this.contextDismissed = true; this.render(); });
    this.root.querySelectorAll<HTMLButtonElement>("[data-tab]").forEach(button => button.addEventListener("click", () => { this.activeTab = button.dataset.tab === "chat" ? "chat" : "activity"; this.error = ""; this.render(); this.scrollMessages(); }));
    this.root.querySelectorAll<HTMLButtonElement>("[data-activity-open]").forEach(button => button.addEventListener("click", () => { const activity = this.activities.find(item => item.id === button.dataset.activityOpen); if (activity) void this.markActivity(activity, "read"); })); this.root.querySelectorAll<HTMLButtonElement>("[data-activity-dismiss]").forEach(button => button.addEventListener("click", event => { event.stopPropagation(); const activity = this.activities.find(item => item.id === button.dataset.activityDismiss); if (activity) void this.markActivity(activity, "dismiss"); }));
    const textarea = this.root.querySelector<HTMLTextAreaElement>(".composer textarea"); textarea?.addEventListener("input", () => { this.draft = textarea.value; }); textarea?.addEventListener("keydown", event => { if (event.key === "Enter" && !event.shiftKey) { event.preventDefault(); void this.sendMessage(); } }); this.root.querySelector<HTMLFormElement>(".composer")?.addEventListener("submit", event => { event.preventDefault(); void this.sendMessage(); });
  }
}

