export const HERON_CONTEXT_VERSION = 1;

export const APP_SURFACE = Object.freeze({
  feed: "feed",
  learn: "learn",
  watch: "watch",
  graph: "graph",
  heronclient: "client",
});

const SURFACES = new Set(["feed", "learn", "watch", "client", "graph"]);
const UUID_FIELDS = Object.freeze({
  trace: "traceId",
  capsule: "capsuleId",
  object: "semanticObjectId",
  projection: "projectionId",
  learning_unit: "learningUnitId",
  action_intent: "actionIntentId",
});
const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const DOMAIN_PATTERN = /^[a-z0-9][a-z0-9-]{0,119}$/;
const ARCHETYPAL_MODES = new Set(["genealogist", "depth_diver", "cross_examiner", "optimizer"]);
const STORAGE_PREFIX = "heron-context:v1:";

function searchParams(input) {
  if (input instanceof URLSearchParams) return input;
  if (input instanceof URL) return input.searchParams;
  const value = String(input || "").trim();
  if (value.startsWith("?") || !value.includes("://")) return new URLSearchParams(value.replace(/^\?/, ""));
  return new URL(value).searchParams;
}

function assertSurface(value, field) {
  if (!SURFACES.has(value)) throw new Error(`${field} is not a supported Heron surface`);
  return value;
}

function safeSourceUrl(value) {
  if (!value) return undefined;
  if (value.length > 2048) throw new Error("source_url exceeds 2048 characters");
  const url = new URL(value);
  const localHttp = url.protocol === "http:" && ["localhost", "127.0.0.1", "::1"].includes(url.hostname);
  if (url.protocol !== "https:" && !localHttp) throw new Error("source_url must use HTTPS (or local HTTP for development)");
  return url.toString();
}

export function parseHeronContext(input, expectedTarget) {
  const params = searchParams(input);
  if (!params.has("heron_v")) return null;

  const version = Number(params.get("heron_v"));
  if (version !== HERON_CONTEXT_VERSION) throw new Error("Unsupported Heron context version");
  const sourceSurface = assertSurface(params.get("heron_from") || "", "heron_from");
  const targetSurface = assertSurface(params.get("heron_to") || "", "heron_to");
  if (expectedTarget && targetSurface !== expectedTarget) throw new Error(`Context targets ${targetSurface}, not ${expectedTarget}`);

  const context = { version, sourceSurface, targetSurface };
  for (const [queryKey, field] of Object.entries(UUID_FIELDS)) {
    const value = params.get(queryKey);
    if (!value) continue;
    if (!UUID_PATTERN.test(value)) throw new Error(`${queryKey} must be a UUID`);
    context[field] = value.toLowerCase();
  }

  const sourceUrl = safeSourceUrl(params.get("source_url") || "");
  if (sourceUrl) context.sourceUrl = sourceUrl;
  const sourceTitle = (params.get("source_title") || "").trim();
  if (sourceTitle.length > 300) throw new Error("source_title exceeds 300 characters");
  if (sourceTitle) context.sourceTitle = sourceTitle;
  const learningDomainId = (params.get("learning_domain") || "").trim();
  if (learningDomainId && !DOMAIN_PATTERN.test(learningDomainId)) throw new Error("learning_domain is invalid");
  if (learningDomainId) context.learningDomainId = learningDomainId;
  const archetypalModes = params.getAll("archetype")
    .flatMap((value) => value.split(","))
    .map((value) => value.trim())
    .filter(Boolean);
  if (archetypalModes.some((mode) => !ARCHETYPAL_MODES.has(mode))) throw new Error("archetype is not supported");
  if (archetypalModes.length > 4) throw new Error("At most four archetypes may be active");
  if (archetypalModes.length) context.archetypalModes = Object.freeze([...new Set(archetypalModes)]);
  const issuedAt = params.get("issued_at");
  if (issuedAt) {
    if (Number.isNaN(Date.parse(issuedAt))) throw new Error("issued_at must be an ISO timestamp");
    context.issuedAt = new Date(issuedAt).toISOString();
  }

  const carriesIdentity = Object.values(UUID_FIELDS).some((field) => context[field]);
  if (!carriesIdentity && !context.learningDomainId && !context.sourceUrl) throw new Error("Heron context must carry an object, trace, capsule, projection, learning unit, learning domain, action intent, or source URL");
  return Object.freeze(context);
}

export function persistHeronContext(context, storage) {
  if (!context || !storage) return;
  storage.setItem(`${STORAGE_PREFIX}${context.targetSurface}`, JSON.stringify(context));
}

export function restoreHeronContext(expectedTarget, storage) {
  if (!expectedTarget || !storage) return null;
  const value = storage.getItem(`${STORAGE_PREFIX}${expectedTarget}`);
  if (!value) return null;
  try {
    const context = JSON.parse(value);
    const params = new URLSearchParams({
      heron_v: String(context.version),
      heron_from: context.sourceSurface,
      heron_to: context.targetSurface,
    });
    for (const [queryKey, field] of Object.entries(UUID_FIELDS)) {
      if (context[field]) params.set(queryKey, context[field]);
    }
    if (context.learningDomainId) params.set("learning_domain", context.learningDomainId);
    if (Array.isArray(context.archetypalModes)) context.archetypalModes.forEach((mode) => params.append("archetype", mode));
    if (context.sourceUrl) params.set("source_url", context.sourceUrl);
    if (context.sourceTitle) params.set("source_title", context.sourceTitle);
    if (context.issuedAt) params.set("issued_at", context.issuedAt);
    return parseHeronContext(params, expectedTarget);
  } catch {
    storage.removeItem(`${STORAGE_PREFIX}${expectedTarget}`);
    return null;
  }
}
